```dart
import 'package:geoflutterfire2/geoflutterfire2.dart';
import 'package:cloud_firestore/cloud_firestore.dart';

final geo = GeoFlutterFire();
final _firestore = FirebaseFirestore.instance;

// Write a point
final point = geo.point(latitude: 12.960632, longitude: 77.641603);
_firestore.collection('locations').add({'name': 'random', 'position': point.data});

// Query nearby points
final center = geo.point(latitude: 12.960632, longitude: 77.641603);
final stream = geo.collection(collectionRef: _firestore.collection('locations'))
    .within(center: center, radius: 50, field: 'position');
stream.listen((docs) => print('Found ${docs.length} docs'));
```
